do $$
declare bad text;
begin
  select string_agg(x.code, ', ') into bad from _new_pt x join public.restaurants r on r.restaurant_code = x.code;
  if bad is not null then raise exception 'PT: codes no longer free: %', bad; end if;
  select string_agg(x.name || ' (' || x.city || ')', ', ') into bad from _new_pt x
   where (select count(*) from public.cities c where c.country_code = 'PT' and c.name = x.city) <> 1;
  if bad is not null then raise exception 'PT: city does not resolve to exactly one row (run the migration first?): %', bad; end if;
  select string_agg(x.name, ', ') into bad from _new_pt x join public.restaurants r on r.michelin_url = x.michelin_url;
  if bad is not null then raise exception 'PT: already present (michelin_url): %', bad; end if;
  select string_agg(x.name, ', ') into bad from _new_pt x join public.restaurants r on r.google_place_id = x.place_id;
  if bad is not null then raise exception 'PT: Place ID already used: %', bad; end if;
end $$;
insert into public.restaurants (restaurant_code, name, michelin_stars, inclusion_reason, city_id, country_code,
                                address, location, michelin_url, website_url, phone, property_name, google_place_id)
select x.code, x.name, x.stars, 'michelin_star',
       (select c.id from public.cities c where c.country_code = 'PT' and c.name = x.city), 'PT',
       x.address, ST_SetSRID(ST_MakePoint(x.lon, x.lat), 4326)::geography,
       x.michelin_url, x.website_url, x.phone, x.property_name, x.place_id
  from _new_pt x;
insert into public.award_history (entity_type, entity_id, guide_year, award_type, award_value, is_current, announced_on)
select 'restaurant', r.id, 2026, 'michelin_stars', x.stars, true, date '2026-03-10'
  from _new_pt x join public.restaurants r on r.restaurant_code = x.code;

-- PT 5. existing rows, fill-only (never overwrites)
create temp table _fill_pt (code text primary key, michelin_url text, phone text, website_url text, place_id text, property_name text) on commit drop;
insert into _fill_pt values
    ('rest_0324', 'https://guide.michelin.com/en/lisboa-region/lisboa/restaurant/belcanto', NULL, 'https://www.belcanto.pt/', NULL, NULL);
do $$
declare bad text;
begin
  select string_agg(f.code, ', ') into bad from _fill_pt f join public.restaurants r on r.michelin_url = f.michelin_url and r.restaurant_code <> f.code;
  if bad is not null then raise exception 'PT: michelin_url used by another row: %', bad; end if;
  select string_agg(f.code, ', ') into bad from _fill_pt f join public.restaurants r on r.google_place_id = f.place_id and r.restaurant_code <> f.code;
  if bad is not null then raise exception 'PT: Place ID used by another row: %', bad; end if;
end $$;
update public.restaurants r set michelin_url = f.michelin_url, updated_at = now() from _fill_pt f where r.restaurant_code = f.code and f.michelin_url is not null and r.michelin_url is null;
update public.restaurants r set phone = f.phone, updated_at = now() from _fill_pt f where r.restaurant_code = f.code and f.phone is not null and r.phone is null;
update public.restaurants r set website_url = f.website_url, updated_at = now() from _fill_pt f where r.restaurant_code = f.code and f.website_url is not null and r.website_url is null;
update public.restaurants r set google_place_id = f.place_id, updated_at = now() from _fill_pt f where r.restaurant_code = f.code and f.place_id is not null and r.google_place_id is null;
update public.restaurants r set property_name = f.property_name, updated_at = now() from _fill_pt f where r.restaurant_code = f.code and f.property_name is not null and r.property_name is null
   and not exists (select 1 from public.hotel_restaurants hr where hr.restaurant_id = r.id);

-- PT post-conditions: MICHELIN's live 2026 listing
do $$
declare n int;
begin
  select count(*) into n from public.restaurants where country_code = 'PT' and michelin_stars = 3;
  if n <> 0 then raise exception 'PT: expected 0 three-star, found %', n; end if;
  select count(*) into n from public.restaurants where country_code = 'PT' and michelin_stars = 2;
  if n <> 9 then raise exception 'PT: expected 9 two-star, found %', n; end if;
  select count(*) into n from public.restaurants where country_code = 'PT' and michelin_stars = 1;
  if n <> 44 then raise exception 'PT: expected 44 one-star, found %', n; end if;
  select count(*) into n from public.restaurants r where r.country_code = 'PT'
     and (select count(*) from public.award_history ah where ah.entity_type = 'restaurant' and ah.entity_id = r.id
           and ah.award_type = 'michelin_stars' and ah.is_current) <> 1;
  if n <> 0 then raise exception 'PT: % restaurants without exactly one current star row', n; end if;
  select count(*) into n from public.restaurants r join public.award_history ah on ah.entity_type = 'restaurant'
     and ah.entity_id = r.id and ah.award_type = 'michelin_stars' and ah.is_current
   where r.country_code = 'PT' and ah.award_value is distinct from r.michelin_stars;
  if n <> 0 then raise exception 'PT: % restaurants disagree with their current award row', n; end if;
  select count(*) into n from public.restaurants r where r.country_code = 'PT' and r.property_name is not null
     and exists (select 1 from public.hotel_restaurants hr where hr.restaurant_id = r.id);
  if n <> 0 then raise exception 'PT: % restaurants have both a hotel link and a property_name', n; end if;
end $$;

commit;
